//! This module uses the rules from the [EBNF module](crate::grammar) to generate the structure of
//! the source code.

use std::collections::HashMap;

use crate::grammar::tree::GrammarNode;

use super::{grammar::tree::Rule, lexing::Token};

/// Represents the combination of the `grammar` rules to the `Lexer` tokens
enum MatchNode {
    Token(Token),
    Rule {
        name: String,
        children: Vec<MatchNode>,
    },
}

/// Matcher of the source code tokens from the `Lexer` to the rules generated by the `grammar lexer`
///
/// There should always be a rule called `program`
struct GrammarMatcher {
    /// All the rules that the user has defined
    rules: HashMap<String, GrammarNode>,
    /// Main tree unit
    main_tree: Option<MatchNode>,
    /// All tokens that have been used to build the current match
    used_tokens: Vec<Token>,
    /// The current node that is being build
    current_node: Option<MatchNode>,
    /// All the possible rules that are left to match with
    possible_rules: Vec<String>,
}

impl GrammarMatcher {
    /// Creates a new `GrammarMatcher` instance
    pub fn new(rules: Vec<Rule>) -> Self {
        // Creating the rules map
        let mut map = HashMap::new();
        for rule in rules {
            if let Some(node) = rule.body {
                map.insert(rule.head, node);
            }
        }
        Self {
            rules: map,
            main_tree: None,
            current_node: Some(MatchNode::Rule {
                name: "program".to_owned(),
                children: vec![],
            }),
            used_tokens: vec![],
            possible_rules: vec![],
        }
    }

    /// Processes the next token
    pub fn process_next(&mut self, next: Token) {
        todo!()
    }

    /// Checks whether a certain rule is valid inside the given tokens,
    /// not all tokens need to match. Only the first to nth token need to fully match. It returns
    /// the tokens wich matched
    ///
    /// # Error
    /// Returns an `None` value if there was no match or something unexpected but recoverable
    /// happened
    fn matches<'a>(&self, tokens: &'a [Token], rule: &GrammarNode) -> Option<&'a [Token]> {
        println!("processing rule: {:?}", rule);
        match rule {
            GrammarNode::Sequence(list) => {
                let mut first_index = 0;
                for i in list {
                    if let Some(matched_slice) = self.matches(&tokens[first_index..], i) {
                        first_index += matched_slice.len();
                    } else {
                        println!("sequence none");
                        return None;
                    }
                }
                Some(&tokens[..first_index])
            }
            GrammarNode::Reference(reference) => {
                if let Some(new_rule) = self.rules.get(reference) {
                    self.matches(tokens, new_rule)
                } else {
                    println!("reference none");
                    None
                }
            }
            GrammarNode::Choice(to_choose) => {
                for i in to_choose {
                    let result = self.matches(tokens, i);
                    if result.is_some() {
                        return result;
                    }
                }
                println!("choice none");
                None
            }
            GrammarNode::Literal(literal) => {
                if tokens.len() == 0 {
                    panic!("Fuck");
                }
                let first_token = &tokens[0];
                println!("{:?}, {literal}", first_token);
                if first_token.body == *literal {
                    Some(&tokens[0..1])
                } else {
                    None
                }
            }
            GrammarNode::ZeroOrMore(internal_rule) => {
                let mut range = 0;
                while let Some(v) = self.matches(&tokens[range..], internal_rule) {
                    println!("looping");
                    range += v.len()
                }
                Some(&tokens[..range])
            }
            other => {
                println!("Got here with: ({:?})", other);
                todo!()
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use crate::{
        grammar::tree::{GrammarNode, Rule},
        lexing::Token,
        parsing::GrammarMatcher,
    };
    #[test]
    fn match_tokens_with_rule() {
        let tokens = vec![
            Token {
                head: "INTEGER".to_owned(),
                body: "5".to_owned(),
            },
            Token {
                head: "PLUS_OPERATOR".to_owned(),
                body: "+".to_owned(),
            },
            Token {
                head: "INTEGER".to_owned(),
                body: "15".to_owned(),
            },
        ];
        let operator_rule = Rule {
            head: "addition".to_owned(),
            body: Some(GrammarNode::Sequence(vec![
                GrammarNode::Reference("integer".to_owned()),
                GrammarNode::Literal("+".to_owned()),
                GrammarNode::Reference("integer".to_owned()),
            ])),
        };
        let digit_rule = Rule {
            head: "digit".to_owned(),
            body: Some(GrammarNode::Choice(vec![
                GrammarNode::Literal("0".to_owned()),
                GrammarNode::Literal("1".to_owned()),
                GrammarNode::Literal("2".to_owned()),
                GrammarNode::Literal("3".to_owned()),
                GrammarNode::Literal("4".to_owned()),
                GrammarNode::Literal("5".to_owned()),
                GrammarNode::Literal("6".to_owned()),
                GrammarNode::Literal("7".to_owned()),
                GrammarNode::Literal("8".to_owned()),
                GrammarNode::Literal("9".to_owned()),
            ])),
        };
        let number_rule = Rule {
            head: "integer".to_owned(),
            body: Some(GrammarNode::Sequence(vec![
                GrammarNode::Reference("digit".to_owned()),
                GrammarNode::ZeroOrMore(Box::new(GrammarNode::Reference("digit".to_owned()))),
            ])),
        };
        let operator_nodes = operator_rule.body.clone().unwrap();
        let matcher = GrammarMatcher::new(vec![operator_rule, digit_rule, number_rule]);
        assert_eq!(
            matcher.matches(&tokens, &operator_nodes),
            Some(tokens.as_slice())
        );
    }
}
